INSERT INTO `npc_text_locale` (`ID`,`Locale`,`Text0_0`,`Text1_0`,`Text2_0`,`Text3_0`,`Text4_0`,`Text5_0`,`Text6_0`,`Text7_0`) VALUES
(@CHATTER_TEXTS_START+0,'deDE','hallo|hallöchen|huhu|moin|moinsen|servus|grüß dich|grüß euch|grüezi|guten tag|guten morgen|guten abend|tach|hey|hi|sei gegrüßt|seid gegrüßt',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+1,'deDE','tschüss|tschüs|tschau|ciao|bis dann|bis später|bis bald|auf wiedersehen|wiedersehen|lebt wohl|leb wohl|mach\'s gut|machs gut|gute nacht|ade',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+2,'deDE','Hallo, %target!','Hi, %target.','Sei gegrüßt, %target!','Grüß dich, %target.','Hey %target, wie läuft\'s?','Schön, dich zu sehen, %target.','Oh, hallo!','Hi! Schönes Wetter heute in %zone, oder?'),
(@CHATTER_TEXTS_START+3,'deDE','Hey %target! Gute Reise.','Heil dir, %target!','Hallo, %target. Brauchst du Hilfe bei irgendwas?','Ah, noch ein Abenteurer. Hallo, %target!','Guten Abend, %target. Oder ist es Morgen? Hier draußen verliere ich jedes Zeitgefühl.','Hi %target! Pass hier draußen auf dich auf.','Möge deine Klinge scharf bleiben, %target.','Oh, hey %target! Was für ein Zufall, dich hier in %zone zu treffen.'),
(@CHATTER_TEXTS_START+4,'deDE','Hallo, %target!','Hi %target!','Hey! Schön, dich zu sehen, %target.','Sei gegrüßt, %target. Was führt dich hierher?','Hi! Kann ich dir irgendwie helfen?','Freut mich, %target.','Oh, hi! Hab dich gar nicht gesehen.','Hey %target, wie geht\'s dir?'),
(@CHATTER_TEXTS_START+5,'deDE','Tschüss, %target!','Man sieht sich, %target.','Pass auf dich auf!','Leb wohl, %target. Gute Reise.','Tschüss! Lass dich von nichts fressen.','Bis später, %target!','Bis zum nächsten Mal.','Viel Glück da draußen, %target.'),
(@CHATTER_TEXTS_START+6,'deDE','Hat jemand Lust auf ein Abenteuer in %zone?','Sucht eine Gruppe noch Verstärkung? %class hier!','%class auf Stufe %level sucht Gesellschaft.','Langweilig...','Macht gerade irgendwer was Spannendes?','Fühlt sich hier draußen noch jemand einsam?','Vielleicht ein Duell irgendwo in %zone?','Wer will sich zusammentun?'),
(@CHATTER_TEXTS_START+7,'deDE','Ruhig heute in %zone. Zu ruhig.','Ich könnte eine Pause gebrauchen. Meine Füße bringen mich um.','Hat jemand ein anständiges Gasthaus in %zone gesehen?','Ich schwöre, die Monster hier werden jeden Tag zäher.','Kennt jemand einen guten Angelplatz hier in der Nähe?','Was für ein schöner Tag in %zone.','Suche einen Freund.','Notiz an mich: mehr Verbände kaufen.'),
(@CHATTER_TEXTS_START+8,'deDE','Ist hier noch ein anderer %race? Lasst uns zusammenhalten.','Biete meine Dienste als %class an. Bezahlung in Gold oder Keksen.','Wo war nochmal der nächste Flugmeister?','Liegt\'s an mir, oder ist %zone größer, als es auf der Karte aussieht?','Ich könnte jetzt echt was zu trinken vertragen.','Hört das noch jemand? Nein? Dann wohl nur ich.','Suche eine Gilde, die sich selbst nicht zu ernst nimmt.','Jedes Mal, wenn ich meine Ausrüstung reparieren lasse, werde ich ein bisschen ärmer.'),
(@CHATTER_TEXTS_START+9,'deDE','%target erledigt.','Und schon wieder liegt %target am Boden.','%target ist Geschichte.','Um %target hab ich mich gekümmert.','%target beißt ins Gras.','Einfach. Der Nächste!','%target wird niemandem mehr Ärger machen.','Und bleib liegen, %target.'),
(@CHATTER_TEXTS_START+10,'deDE','%target besiegt! Das war heftig.','%target war zäh, aber nicht zäh genug.','Puh... %target liegt endlich.','Hat das jemand gesehen? Ich hab gerade %target besiegt!','%target, Stufe %target_level. Nicht schlecht für Stufe %level.','%target hat zugeschlagen wie ein Kodo. Trotzdem gewonnen.','Elite, haben sie gesagt. Gefährlich, haben sie gesagt. %target liegt.','Nach %target muss ich erst mal durchatmen.'),
(@CHATTER_TEXTS_START+11,'deDE','%target gefunden und erledigt! Seltener Gegner, yeah!','Ratet mal, wer gerade %target in %zone erledigt hat?','%target liegt. Tut mir leid, Jäger seltener Gegner, vielleicht nächstes Mal.','Endlich hab ich %target! Danach hab ich lange gesucht.','Seltener Fang: %target. Heute ist ein guter Tag.','%target streift nicht mehr durch %zone.','Wow, %target! Damit hätte ich nicht gerechnet.','Sorry, Jäger: %target gehört mir.'),
(@CHATTER_TEXTS_START+12,'deDE','%target ist gefallen!','Geschafft! %target ist besiegt!','%target ist nicht mehr. Sieg!','So wird das gemacht! Leb wohl, %target.','%target liegt! Zeit für Beute!','Wieder ein Boss weniger: %target.','Sieg über %target! Man wird Lieder darüber singen.','%target dachte, wir wären aufzuhalten. Falsch gedacht.'),
(@CHATTER_TEXTS_START+13,'deDE','Netter Versuch, %target.','%target, vielleicht klappt\'s beim nächsten Mal.','Nimm\'s nicht persönlich, %target.','Das hast du davon, %target!','Ruhe in Frieden, %target.','Steh auf, %target, und versuch\'s noch mal.','Der Sieg ist mein!','Zu langsam, %target.'),
(@CHATTER_TEXTS_START+14,'deDE','Ding!','Ja! Ich bin Stufe %level!','Stufenaufstieg! Jetzt Stufe %level!','Ding! Stufe %level erreicht!','Endlich Stufe %level!','Ich fühle mich schon stärker. Stufe %level!','Stufe %level. Das Grinden zahlt sich aus.','Juhu, %class auf Stufe %level!'),
(@CHATTER_TEXTS_START+15,'deDE','irgendwo',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+16,'deDE','Was gibt\'s, %target?','Hm? Brauchst du was, %target?','Ich höre, %target.','Kann nicht lange reden, ich bin gerade in %zone unterwegs.','Klar, klar. Wie du meinst, %target.','Tut mir leid, %target, ich weiß nicht genau, was du meinst.','Interessant. Erzähl mir ein andermal mehr davon.','Ha! Der war gut, %target.'),
(@CHATTER_TEXTS_START+17,'deDE','Bin am Kämpfen, später!','Nicht jetzt, %target!','Ich stecke hier gerade mitten in etwas!','Moment, ich kämpfe gerade!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+18,'deDE','Endlich %zone.','Das ist also %zone. Sieht ganz nett aus.','Ah, %zone. Ist eine Weile her.','Willkommen in %zone, %name. Versuch nicht zu sterben.','%zone... Ich habe Geschichten über diesen Ort gehört.','Endlich raus da. Hallo, %zone!','Mal sehen, was %zone zu bieten hat.','In %zone verlaufe ich mich immer.'),
(@CHATTER_TEXTS_START+19,'deDE','Oh nein, %target!','%target, alles in Ordnung?! ...Nein, offensichtlich nicht.','Ruh dich aus, %target. Der Geistheiler flickt dich wieder zusammen.','Das sah schmerzhaft aus, %target.','Hilft mal jemand %target!','Zu spät... Tut mir leid, %target.','Autsch. Halt durch, %target.','%target ist gefallen! Vorsicht, alle!'),
(@CHATTER_TEXTS_START+20,'deDE','Glückwunsch zu Stufe %target_level, %target!','Ding! Gut gemacht, %target!','Schon Stufe %target_level? Beeindruckend, %target.','Schau dich an, %target. Jeden Tag stärker.','Gz, %target!','Noch eine Stufe für %target! Die Runde geht auf dich.','Hart verdient, %target.','%target, du überholst mich bald.'),
(@CHATTER_TEXTS_START+21,'deDE','Guten Morgen zusammen!','Was für ein frischer Morgen in %zone.','Der frühe Vogel fängt die Beute.','Ich brauche Frühstück. Und Kaffee. Vor allem Kaffee.','Die Sonne ist auf, lasst uns losziehen.','Hat noch jemand letzte Nacht auf einem Stein geschlafen?','Moin! Schon Pläne für heute?','Ein neuer Tag, neue Abenteuer.'),
(@CHATTER_TEXTS_START+22,'deDE','Wird spät. Zeit, bald ein Gasthaus zu suchen.','Schöner Sonnenuntergang über %zone.','Noch ein Kampf, dann mache ich Feierabend.','Guten Abend zusammen.','Die Monster werden mutiger, wenn es dunkel wird.','Hat heute Abend jemand Lust auf einen Trunk?','Langer Tag. Meine Füße stimmen zu.','Die Abendluft in %zone ist angenehm.'),
(@CHATTER_TEXTS_START+23,'deDE','Warum bin ich eigentlich noch wach?','Ruhige Nacht in %zone.','Ich sehe kaum, wohin ich laufe.','Die Sterne leuchten heute Nacht hell.','Mal wieder Nachtschicht.','Da draußen im Dunkeln bewegt sich etwas...','Kann noch jemand nicht schlafen?','Nachts klingt alles gruseliger.'),
(@CHATTER_TEXTS_START+24,'deDE','Toll, Regen. Einfach toll.','Meine Stiefel sind voller Wasser.','Schon wieder Regen in %zone...','Wenigstens wäscht der Regen das Blut ab.','Hat jemand einen Umhang übrig? Einen trockenen?','Ich liebe den Geruch von Regen.','Die Murlocs lieben dieses Wetter bestimmt.','Nass bis auf die Knochen.'),
(@CHATTER_TEXTS_START+25,'deDE','Brr, ist das kalt!','Schnee! Hat jemand Lust auf eine Schneeballschlacht?','Ich spüre meine Zehen nicht mehr.','Alles ist so still, wenn es schneit.','Ich hätte wärmere Sachen einpacken sollen.','Schnee in %zone. Schön und kalt.','Mein Bart ist gefroren. Und ich hab nicht mal einen Bart.','Heiße Suppe. Ich brauche heiße Suppe.'),
(@CHATTER_TEXTS_START+26,'deDE','Was für ein Sturm!','Ich sehe kaum meine eigene Hand.','Sucht Schutz, der Sturm wird schlimmer!','Sand in meiner Rüstung. Überall.','Der Himmel ist heute zornig.','Hat der Donner gerade den Boden erschüttert?','Nicht das beste Reisewetter.','Haltet eure Hüte fest!'),
(@CHATTER_TEXTS_START+27,'deDE','Was für ein wunderbarer Tag!','Heute könnte ich es mit einem Drachen aufnehmen!','Das Leben ist schön.','Will jemand einen Witz hören? Nein? Schade, ich hab trotzdem gute Laune.','Hehe, heute läuft einfach alles.','Lächelt mal alle!','%zone ist heute herrlich, oder?','Ich liebe es, Abenteurer zu sein.'),
(@CHATTER_TEXTS_START+28,'deDE','Heute geht alles schief.','Lasst mich in Ruhe.','Warum will mich in %zone alles beißen?','Schlechtester. Tag. Überhaupt.','Sprecht mich nicht an, bevor ich was getrunken hab.','Hmpf.','Ich hätte im Bett bleiben sollen.','Dafür wird jemand bezahlen.'),
(@CHATTER_TEXTS_START+29,'deDE','*gähn*','Ein Nickerchen wäre jetzt gut.','Meine Beine fühlen sich an wie Blei.','Wie weit ist es bis zum nächsten Gasthaus?','Nur noch fünf Minuten...','Ich laufe schon seit Stunden.','Brauche... Pause...','Ich bin zu alt für so was.'),
(@CHATTER_TEXTS_START+30,'deDE','Hey %target, ich hänge auch an "%quest". Wollen wir uns zusammentun? Ich hab dich eingeladen.','%target, "%quest" ist allein zu heftig. Sollen wir das zusammen machen?','Ich hab gesehen, du arbeitest an "%quest". Komm in meine Gruppe, dann kriegen wir das hin!','Suchst du auch Hilfe bei "%quest"? Nimm meine Einladung an!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+31,'deDE','Hat jemand Lust auf %dungeon? Wir haben noch Platz!','Suchen noch Leute für %dungeon, alle Rollen willkommen!','Wir gehen bald nach %dungeon. Wer kommt mit?','Gruppe für %dungeon in Planung, flüstert mich an!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+32,'deDE','%target, wir gehen nach %dungeon. Kommst du mit? Nimm meine Einladung an!','Hey %target, uns fehlt noch jemand für %dungeon. Interesse?','%dungeon, du, ich und ein paar Freunde. Was meinst du, %target?',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+33,'deDE','Die brauche ich auch für "%quest"!','Hey, ich bin auch hinter %enemy her. Ich helfe dir!','"%quest"? Ich auch! Machen wir die zusammen platt.','Brauchst du Hilfe mit %enemy? Bin dabei!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+34,'deDE','Sollen wir uns zusammentun, bis wir mit "%quest" fertig sind?','Zusammen geht es schneller. Gruppe für "%quest"?','Wollen wir uns die Kills für "%quest" teilen? Ich hab dich eingeladen.',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+35,'deDE','Wir sammeln uns gegen %boss in %place! Wer ist dabei?','%boss wurde in %place gesichtet. Schlachtzug wird gebildet, macht mit!','Zeit, %boss in %place in die Schranken zu weisen. Wir brauchen Kämpfer!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+36,'deDE','%target, wir nehmen es mit %boss in %place auf. Komm in unseren Schlachtzug!','Hey %target, Lust auf %boss? Wir haben einen Schlachtzug für %place bereit.','%boss in %place, heute noch. Bist du dabei, %target?',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+37,'deDE','Schlachtzug für %raid wird gebildet. Wir brauchen starke Kämpfer!','Suchen noch Leute für %raid, besonders Tanks und Heiler!','Wer will Beute aus %raid? Kommt in unseren Schlachtzug!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+38,'deDE','%target, willst du mit uns nach %raid? Nimm die Einladung an, wir kommen zu dir.','Hey %target, wir gehen nach %raid und haben noch einen Platz für dich.','%raid braucht Helden, %target. Kommst du?',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+39,'deDE','Super, los geht\'s!','Willkommen an Bord, %target!','Ausgezeichnet. Geh voran!','Perfekt, die anderen sind schon unterwegs.',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+40,'deDE','Schade. Vielleicht ein andermal.','Kein Problem, viel Glück da draußen!','Na gut, dann frage ich jemand anderen.',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+41,'deDE','Erledigt. Danke für die Hilfe, %target! Viel Glück.','Geschafft! Ich mache mich jetzt auf den Weg. Pass auf dich auf, %target.','Gute Arbeit, alle zusammen. Lebt wohl!','Es war mir eine Ehre, %target. Bis zum nächsten Mal!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+42,'deDE','Ich muss jetzt los. Leb wohl, %target!','Tut mir leid, die Pflicht ruft. Viel Glück!','Das hat lange genug gedauert, ich ziehe weiter. Pass auf dich auf!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+43,'deDE','Wir greifen das Lager der %enemy da drüben an! Wer ist dabei?','Diese %enemy haben genug Ärger gemacht. Sammelt euch bei mir!','Zu den Waffen! Wir räumen das Lager der %enemy aus!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+44,'deDE','Wir greifen das Lager der %enemy in %zone an, macht mit!','Wir räumen in %zone bei den %enemy auf. Jeder in der Nähe ist willkommen!',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+45,'deDE','%enemy wurde hier in der Nähe gesichtet! Jagen wir es gemeinsam!','Jäger, sammelt euch! %enemy ist ganz in der Nähe!','Ich habe die Spuren von %enemy gefunden. Wer macht bei der Jagd mit?',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+46,'deDE','Wir jagen %enemy in %zone, will jemand mit?','%enemy in %zone gesichtet! Jagdgesellschaft wird gebildet.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+47,'deDE','Angriff!','Jetzt! Los!','Für den Ruhm!','Keine Gnade!',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+48,'deDE','Sieg! Danke an alle, die mitgemacht haben.','Das war es mit %enemy. Gut gekämpft!','Geschafft! Am nächsten Gasthaus geht die Runde auf mich.',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+49,'deDE','Lassen wir es gut sein, das führt zu nichts.','Rückzug! Wir versuchen es ein andermal.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+50,'deDE','Ich bin dabei!','Direkt hinter dir!','Packen wir es an!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+51,'deDE','ja|jo|jep|klar|gerne|gern|okay|ok|na klar|bin dabei|einladen|inv|warum nicht|los geht\'s|auf geht\'s',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+52,'deDE','nein|nö|nee|ne|nein danke|jetzt nicht|vielleicht später|später',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+53,'deDE','Tut mir leid, es hat sich was geändert.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+54,'deDE','Hey %target! Schön, dich wiederzusehen!','%target! Hier drüben!','Sieh an, wer da ist! Hallo, %target!','%target, mein Freund! Wie ist es dir ergangen?','Ah, %target. Immer wieder eine Freude.',NULL,NULL,NULL),
(@CHATTER_TEXTS_START+55,'deDE','Oh. Du bist es, %target.','Nicht du schon wieder.','Geh einfach weiter, %target.','Ich erinnere mich an dich, %target. Und nicht gern.','Hmpf. %target.',NULL,NULL,NULL),
(@CHATTER_TEXTS_START+56,'deDE','%target! Mein alter Freund!','Na, wenn das nicht %target ist! Wie geht es dir?','%target! Das ist viel zu lange her.','Schön, dich in einem Stück zu sehen, %target.',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+57,'deDE','Darf ich dich ein Stück begleiten, %target?','Lass uns ein Stück zusammen reisen, %target.','Warte auf mich, %target, ich komme mit!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+58,'deDE','Du schon wieder, %target?','Geh mir aus dem Weg, %target.','Immer noch am Leben, %target? Schade.','%target. Ich hatte gehofft, dir nicht zu begegnen.',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+59,'deDE','Kümmer dich um deinen eigenen Kram, %target.','Große Worte von dir, %target.','Sag das noch mal und du wirst sehen, was passiert, %target.','Für dich habe ich keine Zeit, %target.',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+60,'deDE','Hat jemand %rival gesehen? Schuldet mir noch zehn Gold.','Wenn ihr %rival trefft, glaubt kein Wort.','%rival könnte nicht mal eine Trainingspuppe treffen.','Komisch, dass %rival immer erst nach dem Kampf auftaucht.',NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+61,'deDE','Ich gehe jetzt meiner eigenen Wege. Bis bald, mein Freund!','Das war eine schöne Reise. Pass auf dich auf!','Hier trennen sich unsere Wege. Leb wohl!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+62,'deDE','Verkaufe %item für %price, flüstert mir "kaufen"!','%item zu verkaufen, %price. Flüstert mich an!','%item für nur %price, wer zuerst kommt...!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+63,'deDE','Kaufe %count x %item, zahle %price pro Stück. Flüstert mir "verkaufen"!','Suche %count x %item, %price pro Stück.','Hat jemand %count x %item? Zahle %price pro Stück.',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+64,'deDE','Gutes Geschäft! %item gehört dir.','Abgemacht! Viel Spaß mit %item.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+65,'deDE','Danke! Hier sind %price für die Ware.','Perfekt, genau was ich brauchte. %price für dich.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+66,'deDE','Das ist nicht genug Gold, mein Freund.','Komm wieder, wenn du es dir leisten kannst.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+67,'deDE','Deine Taschen sind voll. Mach erst mal Platz!',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+68,'deDE','Du hast keine %count x %item.','Komm wieder, wenn du %count x %item hast.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+69,'deDE','kaufen|kauf|ich kaufe|ich nehme|nehme|verkaufen|verkauf|ich verkaufe|deal|abgemacht|gekauft|hab ich|habe ich',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+70,'deDE','Tut mir leid, das ist schon weg.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+71,'deDE','Zu den Waffen! %enemy greift %town an!','%enemy kommt nach %town! Verteidigt die Stadt!','Alle zu mir! %enemy greift %town an!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+72,'deDE','%enemy greift %town an! Alle Verteidiger werden gebraucht!','%town wird von %enemy angegriffen! Hilfe!',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+73,'deDE','Da kommen noch mehr!','Noch eine Welle! Haltet die Stellung!','Es werden immer mehr! Haltet durch!',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+74,'deDE','%town ist sicher! Danke, Verteidiger!','Wir haben sie zurückgeschlagen! Gut gekämpft, alle zusammen!',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+75,'deDE','Wir konnten sie nicht aufhalten... Sie ziehen sich vorerst zurück.','Rückzug! Wir bauen %town wieder auf.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+76,'deDE','Holen wir uns %objective!','%objective gehört uns. Los geht\'s!','Zeit, %objective zurückzuerobern.',NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+77,'deDE','Wir ziehen zu %objective, helft uns, es einzunehmen!','Angriff auf %objective, jeder ist willkommen!',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+78,'deDE','%objective gehört uns!','Wir halten %objective! Gut gemacht!',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+79,'deDE','Wir konnten %objective nicht einnehmen. Rückzug!','Zu viele von ihnen bei %objective. Nächstes Mal.',NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+80,'deDE','Die Geißel',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+81,'deDE','Die Brennende Legion',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+82,'deDE','Eine Räuberbande',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+83,'deDE','%player hat %place gegen %subject verteidigt.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+84,'deDE','%player hat geholfen, die %subject bei %place zu vertreiben.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+85,'deDE','%player hat %subject bei %place zur Strecke gebracht.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+86,'deDE','%player hat geholfen, %subject in %place einzunehmen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+87,'deDE','%player hat %subject in %place besiegt!',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+88,'deDE','%player hat %subject bezwungen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(@CHATTER_TEXTS_START+89,'deDE','%player hat die Sache mit "%subject" bei %place erledigt.',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
